static const size_t kLen49 = 18953;

static std::string AssembleString(const char **data, size_t len) {
  std::string ret;
  for (size_t i = 0; i < len; i += 8192) {
    size_t chunk = std::min(static_cast<size_t>(8192), len - i);
    ret.append(data[i / 8192], chunk);
  }
  return ret;
}

